import React, { useState, useEffect, useMemo, useCallback } from 'react';
import { useTranslation } from 'react-i18next';
import Icon from '../../../components/AppIcon';
import Button from '../../../components/ui/Button';
import Input from '../../../components/ui/Input';
import Select from '../../../components/ui/Select';
import TranslationTreeView from './TranslationTreeView';
import TranslationEditModal from './TranslationEditModal';
import TranslationImportModal from './TranslationImportModal';
import MissingTranslationsModal from './MissingTranslationsModal';
import { translationService } from '../../../services/translationService';

const TranslationManagementPanel = ({ onRefresh, onShowToast }) => {
  const { i18n } = useTranslation();

  // State
  const [translations, setTranslations] = useState({});
  const [selectedLanguage, setSelectedLanguage] = useState('en');
  const [selectedCategory, setSelectedCategory] = useState('all');
  const [searchQuery, setSearchQuery] = useState('');
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState('');

  // Modals
  const [showEditModal, setShowEditModal] = useState(false);
  const [showImportModal, setShowImportModal] = useState(false);
  const [showMissingModal, setShowMissingModal] = useState(false);
  const [selectedKey, setSelectedKey] = useState(null);
  const [missingTranslations, setMissingTranslations] = useState([]);

  // View options
  const [expandedCategories, setExpandedCategories] = useState(new Set(['common']));

  // Load translations
  const loadTranslations = useCallback(async () => {
    try {
      setIsLoading(true);
      setError('');

      const data = await translationService.getTranslations(selectedLanguage);
      setTranslations(data);
    } catch (err) {
      console.error('Error loading translations:', err);
      setError('Failed to load translations');
      onShowToast?.('Failed to load translations', true);
    } finally {
      setIsLoading(false);
    }
  }, [selectedLanguage, onShowToast]);

  useEffect(() => {
    loadTranslations();
  }, [loadTranslations]);

  // Group translations by category
  const grouped = useMemo(() => {
    const result = {};

    Object.entries(translations).forEach(([key, value]) => {
      // Apply search filter
      if (searchQuery) {
        const query = searchQuery.toLowerCase();
        const matchesKey = key.toLowerCase().includes(query);
        const matchesValue = value?.toLowerCase().includes(query);
        if (!matchesKey && !matchesValue) return;
      }

      const category = key.split('.')[0];

      // Apply category filter
      if (selectedCategory !== 'all' && category !== selectedCategory) {
        return;
      }

      if (!result[category]) {
        result[category] = [];
      }

      result[category].push({ key, value });
    });

    return result;
  }, [translations, searchQuery, selectedCategory]);

  // Get unique categories
  const categories = useMemo(() => {
    return [...new Set(Object.keys(translations).map(key => key.split('.')[0]))].sort();
  }, [translations]);

  // Find missing translations
  const handleFindMissing = async () => {
    try {
      const missing = await translationService.detectMissing();
      setMissingTranslations(missing);
      setShowMissingModal(true);
    } catch (err) {
      onShowToast?.('Failed to detect missing translations', true);
    }
  };

  // Export translations
  const handleExport = async () => {
    try {
      const blob = await translationService.exportTranslations(selectedLanguage);

      // Download file
      const url = URL.createObjectURL(blob);
      const a = document.createElement('a');
      a.href = url;
      a.download = `translation-${selectedLanguage}-${Date.now()}.json`;
      document.body.appendChild(a);
      a.click();
      document.body.removeChild(a);
      URL.revokeObjectURL(url);

      onShowToast?.('Translations exported successfully');
    } catch (err) {
      onShowToast?.('Failed to export translations', true);
    }
  };

  // Handle create new key
  const handleCreate = () => {
    setSelectedKey(null);
    setShowEditModal(true);
  };

  // Handle edit
  const handleEdit = async (keyPath) => {
    // Load values for all languages
    const allLanguages = ['en', 'nl', 'fr', 'de'];
    const values = {};

    try {
      for (const lang of allLanguages) {
        const langTranslations = await translationService.getTranslations(lang);
        values[lang] = langTranslations[keyPath] || '';
      }

      setSelectedKey({ keyPath, values });
      setShowEditModal(true);
    } catch (err) {
      onShowToast?.('Failed to load translation details', true);
    }
  };

  // Handle save (create or update)
  const handleSave = async (data) => {
    try {
      if (selectedKey) {
        // Update existing
        for (const [lang, value] of Object.entries(data.values)) {
          if (value !== selectedKey.values[lang]) {
            await translationService.updateValue(selectedKey.keyPath, lang, value);
          }
        }
        onShowToast?.('Translation updated successfully');
      } else {
        // Create new
        await translationService.createKey(data.keyPath, data.values);
        onShowToast?.('Translation key created successfully');
      }

      setShowEditModal(false);
      setSelectedKey(null);

      // Reload translations
      await loadTranslations();

      // Reload i18n resources
      await i18n.reloadResources();
    } catch (err) {
      onShowToast?.(err.message || 'Failed to save translation', true);
      throw err; // Re-throw so modal can handle it
    }
  };

  // Handle delete
  const handleDelete = async (keyPath) => {
    if (!confirm(`Delete translation key "${keyPath}"?\n\nThis will remove it from all languages.`)) {
      return;
    }

    try {
      await translationService.deleteKey(keyPath);
      onShowToast?.('Translation key deleted successfully');
      await loadTranslations();
      await i18n.reloadResources();
    } catch (err) {
      onShowToast?.('Failed to delete translation', true);
    }
  };

  // Toggle category expansion
  const handleToggleCategory = (category) => {
    setExpandedCategories((prev) => {
      const next = new Set(prev);
      if (next.has(category)) {
        next.delete(category);
      } else {
        next.add(category);
      }
      return next;
    });
  };

  // Language options
  const languageOptions = [
    { value: 'en', label: 'English' },
    { value: 'nl', label: 'Nederlands' },
    { value: 'fr', label: 'Français' },
    { value: 'de', label: 'Deutsch' }
  ];

  // Category options
  const categoryOptions = [
    { value: 'all', label: 'All Categories' },
    ...categories.map((cat) => ({ value: cat, label: cat }))
  ];

  // Count total keys
  const totalKeys = Object.keys(translations).length;
  const visibleKeys = Object.values(grouped).reduce((sum, items) => sum + items.length, 0);

  return (
    <div className="space-y-6">
      {/* Toolbar */}
      <div className="flex flex-col lg:flex-row gap-4 items-start lg:items-center justify-between">
        <div className="flex flex-wrap gap-3 items-center">
          <Select
            options={languageOptions}
            value={selectedLanguage}
            onChange={(val) => setSelectedLanguage(val)}
            className="w-40"
          />

          <Select
            options={categoryOptions}
            value={selectedCategory}
            onChange={(val) => setSelectedCategory(val)}
            className="w-48"
          />

          <Input
            type="search"
            placeholder="Search keys or values..."
            value={searchQuery}
            onChange={(e) => setSearchQuery(e.target.value)}
            className="w-64"
          />
        </div>

        <div className="flex flex-wrap gap-2">
          <Button
            variant="outline"
            size="sm"
            iconName="AlertCircle"
            onClick={handleFindMissing}
          >
            Find Missing
          </Button>

          <Button
            variant="outline"
            size="sm"
            iconName="Download"
            onClick={handleExport}
          >
            Export
          </Button>

          <Button
            variant="outline"
            size="sm"
            iconName="Upload"
            onClick={() => setShowImportModal(true)}
          >
            Import
          </Button>

          <Button
            variant="primary"
            size="sm"
            iconName="Plus"
            onClick={handleCreate}
          >
            Add Key
          </Button>
        </div>
      </div>

      {/* Stats */}
      <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
        <div className="bg-card border border-border rounded-xl p-4">
          <p className="text-xs text-muted-foreground uppercase tracking-wide">Total Keys</p>
          <p className="text-2xl font-bold text-foreground mt-1">{totalKeys}</p>
        </div>

        <div className="bg-card border border-border rounded-xl p-4">
          <p className="text-xs text-muted-foreground uppercase tracking-wide">Categories</p>
          <p className="text-2xl font-bold text-foreground mt-1">{categories.length}</p>
        </div>

        <div className="bg-card border border-border rounded-xl p-4">
          <p className="text-xs text-muted-foreground uppercase tracking-wide">Language</p>
          <p className="text-2xl font-bold text-foreground mt-1">{selectedLanguage.toUpperCase()}</p>
        </div>

        <div className="bg-card border border-border rounded-xl p-4">
          <p className="text-xs text-muted-foreground uppercase tracking-wide">Showing</p>
          <p className="text-2xl font-bold text-foreground mt-1">{visibleKeys}</p>
        </div>
      </div>

      {/* Loading/Error */}
      {isLoading && (
        <div className="text-center py-12">
          <Icon name="Loader2" className="animate-spin mx-auto mb-2" size={32} />
          <p className="text-muted-foreground">Loading translations...</p>
        </div>
      )}

      {error && !isLoading && (
        <div className="bg-error/10 border border-error/30 rounded-xl p-4">
          <div className="flex items-center gap-2">
            <Icon name="AlertCircle" className="text-error" />
            <p className="text-error font-medium">{error}</p>
          </div>
        </div>
      )}

      {/* Tree View */}
      {!isLoading && !error && (
        <TranslationTreeView
          grouped={grouped}
          expandedCategories={expandedCategories}
          onToggleCategory={handleToggleCategory}
          onEdit={handleEdit}
          onDelete={handleDelete}
        />
      )}

      {/* Empty state */}
      {!isLoading && !error && visibleKeys === 0 && (
        <div className="text-center py-12">
          <Icon name="Search" className="mx-auto mb-3 text-muted-foreground" size={48} />
          <p className="text-lg font-medium text-foreground">No translations found</p>
          <p className="text-sm text-muted-foreground mt-1">
            Try adjusting your search or filters
          </p>
        </div>
      )}

      {/* Modals */}
      {showEditModal && (
        <TranslationEditModal
          translationKey={selectedKey}
          onClose={() => {
            setShowEditModal(false);
            setSelectedKey(null);
          }}
          onSave={handleSave}
        />
      )}

      {showImportModal && (
        <TranslationImportModal
          language={selectedLanguage}
          onClose={() => setShowImportModal(false)}
          onImportComplete={async () => {
            setShowImportModal(false);
            await loadTranslations();
            await i18n.reloadResources();
            onShowToast?.('Import completed successfully');
          }}
        />
      )}

      {showMissingModal && (
        <MissingTranslationsModal
          missingTranslations={missingTranslations}
          onClose={() => setShowMissingModal(false)}
          onAddMissing={(keyPath) => {
            setShowMissingModal(false);
            handleEdit(keyPath);
          }}
        />
      )}
    </div>
  );
};

export default TranslationManagementPanel;
