import React, { useState, useEffect, useCallback, useMemo } from 'react';
import { Helmet } from 'react-helmet';
import AuthContextNavigator from '../../components/navigation/AuthContextNavigator';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';

// Panels
import UserManagementPanel from './components/UserManagementPanel';
import PermissionsManagementPanel from './components/PermissionsManagementPanel';
import WorkflowManagementPanel from './components/WorkflowManagementPanel';
import TranslationManagementPanel from './components/TranslationManagementPanel';
import LoggingPanel from './components/LoggingPanel';

// Services
import { ticketService } from '../../services/ticketService';
import { workflowService } from '../../services/workflowService';
import { permissionService } from '../../services/permissionService';

const StatCard = ({ label, value, icon, toneClass = 'bg-primary/10 text-primary' }) => (
  <div className="bg-card border border-border rounded-2xl p-4">
    <div className="flex items-center justify-between gap-3">
      <div className="min-w-0">
        <p className="text-xs uppercase tracking-wide text-muted-foreground">{label}</p>
        <p className="text-2xl font-bold text-foreground mt-1 truncate">{value}</p>
      </div>
      <div className={`w-11 h-11 rounded-xl flex items-center justify-center ${toneClass}`}>
        <Icon name={icon} size={20} />
      </div>
    </div>
  </div>
);

const Pill = ({ children }) => (
  <span className="inline-flex items-center gap-2 px-3 py-1 rounded-full text-xs bg-muted border border-border text-muted-foreground">
    {children}
  </span>
);

const AdminDashboard = () => {
  const [activeTab, setActiveTab] = useState('users'); // users | permissions | workflows
  const [loading, setLoading] = useState(true);

  const [error, setError] = useState('');
  const [success, setSuccess] = useState('');

  const [query, setQuery] = useState('');

  // Data state
  const [users, setUsers] = useState([]);
  const [permissions, setPermissions] = useState([]);
  const [roles, setRoles] = useState([]);
  const [workflows, setWorkflows] = useState([]);

  const loadAllData = useCallback(async () => {
    try {
      setLoading(true);
      setError('');

      const [usersData, permsData, rolesData, workflowsData] = await Promise.all([
        ticketService.getAllHandlers(),
        permissionService.getAllPermissions(),
        permissionService.getAllRoles(),
        workflowService.getWorkflowsWithStats(),
      ]);

      setUsers(usersData || []);
      setPermissions(permsData || []);
      setRoles(rolesData || []);
      setWorkflows(workflowsData || []);
    } catch (err) {
      console.error('Error loading admin data:', err);
      setError('Fout bij laden van gegevens');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadAllData();
  }, [loadAllData]);

  const showToast = useCallback((message, isError = false) => {
    if (isError) {
      setError(message);
      setTimeout(() => setError(''), 3000);
    } else {
      setSuccess(message);
      setTimeout(() => setSuccess(''), 3000);
    }
  }, []);

  const tabs = useMemo(
    () => [
      {
        id: 'users',
        label: 'Gebruikers',
        icon: 'Users',
        meta: `${users.length} gebruikers`,
        description: 'Accounts, rollen en toegang',
      },
      {
        id: 'permissions',
        label: 'Rechten & Rollen',
        icon: 'Key',
        meta: `${roles.length} rollen`,
        description: 'Permissies per rol beheren',
      },
      {
        id: 'workflows',
        label: 'Workflows',
        icon: 'GitBranch',
        meta: `${workflows.length} Workflows`,
        description: 'Procesflows en statistieken',
      },
      {
        id: 'translations',
        label: 'Vertalingen',
        icon: 'Languages',
        meta: '4 talen',
        description: 'Beheer i18n vertalingen',
      },
      {
        id: 'logging',
        label: 'Audit Logs',
        icon: 'ScrollText',
        meta: 'Database logs',
        description: 'Bekijk database wijzigingen',
      },
    ],
    [users.length, roles.length, workflows.length]
  );

  const active = tabs.find(t => t.id === activeTab);

  // A few global KPIs so the admin always has “where am I” context
  const activeUsers = users.filter(u => u.isActive || u.active).length;
  const systemPerms = permissions.filter(p => p.isSystem).length;

  const filteredUsers = useMemo(() => {
    if (!query.trim()) return users;
    const q = query.toLowerCase();
    return users.filter(u =>
      [u.name, u.email, u.username, ...(u.roles || [])].filter(Boolean).join(' ').toLowerCase().includes(q)
    );
  }, [users, query]);

  const filteredRoles = useMemo(() => {
    if (!query.trim()) return roles;
    const q = query.toLowerCase();
    return roles.filter(r =>
      [r.name, r.code, r.description].filter(Boolean).join(' ').toLowerCase().includes(q)
    );
  }, [roles, query]);

  const filteredPermissions = useMemo(() => {
    if (!query.trim()) return permissions;
    const q = query.toLowerCase();
    return permissions.filter(p =>
      [p.name, p.code, p.description, p.category].filter(Boolean).join(' ').toLowerCase().includes(q)
    );
  }, [permissions, query]);

  const filteredWorkflows = useMemo(() => {
    if (!query.trim()) return workflows;
    const q = query.toLowerCase();
    return workflows.filter(w =>
      [w.name, w.code, w.description].filter(Boolean).join(' ').toLowerCase().includes(q)
    );
  }, [workflows, query]);

  if (loading) {
    return (
      <AuthContextNavigator>
        <div className="min-h-screen bg-background flex items-center justify-center">
          <div className="text-center">
            <Icon name="Loader2" size={48} className="animate-spin text-primary mx-auto mb-4" />
            <p className="text-muted-foreground">Admin gegevens laden...</p>
          </div>
        </div>
      </AuthContextNavigator>
    );
  }

  return (
    <>
      <Helmet>
        <title>Admin Dashboard - Misstanden Portal</title>
        <meta name="description" content="Beheer gebruikers, rechten, rollen en workflows" />
      </Helmet>

      <AuthContextNavigator>
        <div className="min-h-screen bg-background">
          <div className="max-w-[1600px] mx-auto px-4 sm:px-6 lg:px-8 py-6 md:py-8">
            {/* Top Header */}
            <div className="mb-6">
              <div className="flex flex-col gap-4 lg:flex-row lg:items-end lg:justify-between">
                <div>
                  <div className="flex items-center gap-3">
                    <h1 className="text-3xl md:text-4xl font-bold text-sky-600">
                      Admin Center
                    </h1>
                  </div>
                  <p className="mt-2 text-sm md:text-base text-muted-foreground">
                    Eén plek voor beheer van accounts, toegang en workflows.
                  </p>
                </div>

                <div className="flex flex-col sm:flex-row gap-3 sm:items-center">
                  {/* Search */}
                  <div className="relative w-full sm:w-[360px]">
                    <div className="absolute left-3 top-1/2 -translate-y-1/2 opacity-70">
                      <Icon name="Search" size={18} />
                    </div>
                    <input
                      value={query}
                      onChange={(e) => setQuery(e.target.value)}
                      placeholder="Zoek in admin (naam, rol, permission, workflow)..."
                      className="w-full pl-10 pr-10 py-2.5 rounded-xl bg-card border border-border text-sm outline-none focus:ring-2 focus:ring-primary/30"
                    />
                    {query && (
                      <button
                        onClick={() => setQuery('')}
                        className="absolute right-3 top-1/2 -translate-y-1/2 opacity-70 hover:opacity-100"
                        aria-label="Clear"
                      >
                        <Icon name="X" size={18} />
                      </button>
                    )}
                  </div>

                  <Button
                    variant="outline"
                    size="lg"
                    iconName="RefreshCw"
                    iconPosition="left"
                    onClick={loadAllData}
                  >
                    Vernieuwen
                  </Button>
                </div>
              </div>
            </div>

            {/* Global KPI Strip */}
            {/* <div className="grid grid-cols-1 sm:grid-cols-2 xl:grid-cols-4 gap-4 mb-6">
              <StatCard label="Gebruikers" value={users.length} icon="Users" />
              <StatCard
                label="Actief"
                value={activeUsers}
                icon="CheckCircle"
                toneClass="bg-success/10 text-success"
              />
              <StatCard
                label="Rollen"
                value={roles.length}
                icon="Shield"
                toneClass="bg-accent/10 text-accent"
              />
              <StatCard
                label="Permissies"
                value={`${permissions.length} (${systemPerms} systeem)`}
                icon="Key"
                toneClass="bg-warning/10 text-warning"
              />
            </div> */}

            {/* Messages */}
            {(error || success) && (
              <div className="mb-6 space-y-3">
                {error && (
                  <div className="p-4 bg-error/10 border border-error/30 rounded-xl flex items-center gap-3">
                    <Icon name="AlertCircle" size={20} className="text-error" />
                    <p className="text-sm text-error">{error}</p>
                  </div>
                )}
                {success && (
                  <div className="p-4 bg-success/10 border border-success/30 rounded-xl flex items-center gap-3">
                    <Icon name="CheckCircle" size={20} className="text-success" />
                    <p className="text-sm text-success">{success}</p>
                  </div>
                )}
              </div>
            )}

            {/* Main Layout */}
            <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
              {/* Left Navigation */}
              <aside className="lg:col-span-3">
                <div className="bg-card border border-border rounded-2xl p-3 lg:p-4">
                  <div className="flex items-center justify-between mb-3 px-2">
                    <p className="text-xs uppercase tracking-wide text-muted-foreground">Modules</p>
                    {/* <Icon name="LayoutGrid" size={16} className="opacity-70" /> */}
                  </div>

                  <div className="flex lg:flex-col gap-2 overflow-x-auto lg:overflow-visible pb-1 lg:pb-0">
                    {tabs.map(tab => {
                      const isActive = activeTab === tab.id;
                      return (
                        <button
                          key={tab.id}
                          onClick={() => setActiveTab(tab.id)}
                          className={[
                            'flex items-center justify-between gap-3',
                            'min-w-[240px] lg:min-w-0',
                            'px-3 py-3 rounded-xl border transition-all text-left',
                            isActive
                              ? 'bg-primary/10 border-primary/30'
                              : 'bg-background border-border hover:bg-muted/30',
                          ].join(' ')}
                        >
                          <div className="flex items-center gap-3 min-w-0">
                            <div
                              className={[
                                'w-10 h-10 rounded-xl flex items-center justify-center',
                                isActive ? 'bg-primary/15 text-primary' : 'bg-muted text-muted-foreground',
                              ].join(' ')}
                            >
                              <Icon name={tab.icon} size={18} />
                            </div>
                            <div className="min-w-0">
                              <div className="flex items-center gap-2">
                                <p className={`font-semibold ${isActive ? 'text-primary' : 'text-foreground'}`}>
                                  {tab.label}
                                </p>
                                <span className="text-xs px-2 py-0.5 rounded bg-muted border border-border text-muted-foreground">
                                  {tab.meta}
                                </span>
                              </div>
                              <p className="text-xs text-muted-foreground truncate">{tab.description}</p>
                            </div>
                          </div>

                          <Icon
                            name="ChevronRight"
                            size={16}
                            className={`opacity-60 ${isActive ? 'text-primary' : 'text-muted-foreground'}`}
                          />
                        </button>
                      );
                    })}
                  </div>
                </div>

                {/* Small helper card */}
                {/* <div className="mt-4 bg-card border border-border rounded-2xl p-4">
                  <div className="flex items-start gap-3">
                    <div className="w-9 h-9 rounded-xl bg-muted flex items-center justify-center">
                      <Icon name="Info" size={18} className="opacity-80" />
                    </div>
                    <div>
                      <p className="text-sm font-semibold text-foreground">Tip</p>
                      <p className="text-xs text-muted-foreground mt-1">
                        Gebruik de zoekbalk om snel een gebruiker, rol of permission te vinden zonder
                        tab-switch chaos.
                      </p>
                    </div>
                  </div>
                </div> */}
              </aside>

              {/* Right Content */}
              <main className="lg:col-span-9">
                <div className="bg-card border border-border rounded-2xl">
                  {/* Content Header */}
                  <div className="p-5 sm:p-6 border-b border-border">
                    <div className="flex flex-col sm:flex-row sm:items-center sm:justify-between gap-3">
                      <div>
                        <div className="flex items-center gap-2">
                          <Icon name={active?.icon || 'Settings'} size={18} className="text-primary" />
                          <h2 className="text-lg font-semibold text-foreground">{active?.label}</h2>
                        </div>
                        <p className="text-sm text-muted-foreground mt-1">
                          {active?.description}
                        </p>
                      </div>

                      <div className="flex items-center gap-2">
                        <Pill>
                          <Icon name="Filter" size={14} />
                          <span>Zoekfilter actief: </span>
                          <span className="text-foreground/80">{query ? 'ja' : 'nee'}</span>
                        </Pill>
                      </div>
                    </div>
                  </div>

                  {/* Content Body */}
                  <div className="p-5 sm:p-6">
                    {activeTab === 'users' && (
                      <UserManagementPanel
                        users={filteredUsers}
                        roles={roles}
                        workflows={workflows}
                        onRefresh={loadAllData}
                        onShowToast={showToast}
                      />
                    )}

                    {activeTab === 'permissions' && (
                      <PermissionsManagementPanel
                        permissions={filteredPermissions}
                        roles={filteredRoles}
                        users={users}
                        onRefresh={loadAllData}
                        onShowToast={showToast}
                      />
                    )}

                    {activeTab === 'workflows' && (
                      <WorkflowManagementPanel
                        workflows={filteredWorkflows}
                        users={users}
                        onRefresh={loadAllData}
                        onShowToast={showToast}
                      />
                    )}

                    {activeTab === 'translations' && (
                      <TranslationManagementPanel
                        onRefresh={loadAllData}
                        onShowToast={showToast}
                      />
                    )}

                    {activeTab === 'logging' && (
                      <LoggingPanel
                        onShowToast={showToast}
                      />
                    )}
                  </div>
                </div>
              </main>
            </div>
          </div>
        </div>
      </AuthContextNavigator>
    </>
  );
};

export default AdminDashboard;