import React, { useEffect, useMemo, useState } from 'react';
import { Helmet } from 'react-helmet';
import { useTranslation } from 'react-i18next';
import AuthContextNavigator from '../../components/navigation/AuthContextNavigator';
import Icon from '../../components/AppIcon';
import Button from '../../components/ui/Button';
import Input from '../../components/ui/Input';
import { settingsService } from '../../services/SettingsService';
import { useSettings } from '../../contexts/SettingsContext';
import EmailNotificationSettings from './components/EmailNotificationSettings';
import SettingsSection from './components/SettingsSection';

function useCurrentHandler() {
  return { id: 'handler_123', name: 'Jeroen', email: 'jeroen@example.com' };
}

const isEqualJson = (a, b) => {
  try {
    return JSON.stringify(a) === JSON.stringify(b);
  } catch {
    return a === b;
  }
};

const getCategoryMeta = (t) => ({
  general: { label: t('settings.categories.general'), icon: 'Settings', priority: 1 },
  portal: { label: t('settings.categories.portal'), icon: 'Layout', priority: 2 },
  workflow: { label: t('settings.categories.workflow'), icon: 'Workflow', priority: 3 },
  sla: { label: t('settings.categories.sla'), icon: 'Clock', priority: 4 },
  email_notifications: { label: t('settings.categories.email_notifications'), icon: 'Mail', isSpecial: true, priority: 5 },
  notifications: { label: t('settings.categories.notifications'), icon: 'Bell', priority: 6 },
  security: { label: t('settings.categories.security'), icon: 'Shield', isSpecial: true, priority: 7 },
  audit: { label: t('settings.categories.audit'), icon: 'FileSearch', priority: 8 },
  retention: { label: t('settings.categories.retention'), icon: 'Archive', priority: 9 },
  danger: { label: t('settings.categories.danger'), icon: 'AlertTriangle', priority: 10 },
});

export default function SystemSettingsAdmin() {
  const { t } = useTranslation();
  const currentHandler = useCurrentHandler();
  const { reload: reloadGlobalSettings } = useSettings();
  const categoryMeta = useMemo(() => getCategoryMeta(t), [t]);

  const [rows, setRows] = useState([]);
  const [draft, setDraft] = useState({});
  const [original, setOriginal] = useState({});
  const [searchQuery, setSearchQuery] = useState('');
  const [viewMode, setViewMode] = useState('all'); // 'all', 'security', 'email_notifications'

  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [error, setError] = useState('');
  const [successMessage, setSuccessMessage] = useState('');

  const byCategory = useMemo(() => {
    const map = {};
    for (const r of rows) {
      if (!map[r.category]) map[r.category] = [];
      map[r.category].push(r);
    }
    return map;
  }, [rows]);

  const categories = useMemo(() => {
    const found = Object.keys(byCategory);
    const specialCategories = Object.keys(categoryMeta).filter(k => categoryMeta[k].isSpecial);
    const ordered = Object.keys(categoryMeta)
      .filter((k) => found.includes(k) || specialCategories.includes(k))
      .sort((a, b) => (categoryMeta[a]?.priority || 999) - (categoryMeta[b]?.priority || 999));
    return ordered;
  }, [byCategory, categoryMeta]);

  const filteredRows = useMemo(() => {
    if (!searchQuery.trim()) return rows;

    const query = searchQuery.toLowerCase();
    return rows.filter(row =>
      row.setting_key.toLowerCase().includes(query) ||
      row.description?.toLowerCase().includes(query) ||
      row.category?.toLowerCase().includes(query)
    );
  }, [rows, searchQuery]);

  const filteredCategories = useMemo(() => {
    if (viewMode === 'security' || viewMode === 'email_notifications') {
      return [viewMode];
    }

    if (!searchQuery.trim()) return categories;

    const categoriesWithResults = new Set(filteredRows.map(r => r.category));
    return categories.filter(cat => categoriesWithResults.has(cat));
  }, [categories, searchQuery, filteredRows, viewMode]);

  const dirtyKeys = useMemo(() => {
    const keys = Object.keys(draft);
    return keys.filter((k) => !isEqualJson(draft[k], original[k]));
  }, [draft, original]);

  const load = async () => {
    setIsLoading(true);
    setError('');
    try {
      const { rows: dataRows } = await settingsService.getSettings();
      setRows(dataRows);

      const o = {};
      const d = {};
      for (const r of dataRows) {
        o[r.setting_key] = r.setting_value;
        d[r.setting_key] = r.setting_value;
      }
      setOriginal(o);
      setDraft(d);
    } catch (e) {
      console.error(e);
      setError(e?.message || t('settings.messages.errorLoading'));
    } finally {
      setIsLoading(false);
    }
  };

  useEffect(() => {
    load();
  }, []);

  const save = async () => {
    if (!dirtyKeys.length) return;
    setIsSaving(true);
    setError('');
    setSuccessMessage('');

    try {
      const changedItems = dirtyKeys.map((key) => {
        const row = rows.find((r) => r.setting_key === key);
        return {
          settingKey: key,
          value: draft[key],
          category: row?.category || 'general',
          description: row?.description ?? null,
          isSensitive: !!row?.is_sensitive,
        };
      });

      await settingsService.upsertSettings(changedItems, {
        updatedBy: currentHandler?.id || currentHandler?.email || currentHandler?.name || null,
      });

      await load();
      await reloadGlobalSettings();

      setSuccessMessage(t('settings.messages.saveSuccess'));
      setTimeout(() => setSuccessMessage(''), 5000);
    } catch (e) {
      console.error(e);
      setError(e?.message || t('settings.messages.saveError'));
    } finally {
      setIsSaving(false);
    }
  };

  const resetAll = () => {
    setDraft({ ...original });
  };

  return (
    <>
      <Helmet>
        <title>{t('settings.pageTitle')}</title>
      </Helmet>

      <AuthContextNavigator>
        <div className="min-h-screen bg-background py-6 px-4 sm:px-6 lg:px-8 mt-5">
          <div className="max-w-7xl mx-auto">
            {/* Header */}
            <div className="mb-6">
              <h1 className="text-3xl md:text-4xl font-bold text-primary mb-2">
                {t('settings.title')}
              </h1>
              <p className="text-muted-foreground">
                {t('settings.subtitle')}
              </p>
            </div>

            {/* Quick Stats & Actions Bar */}
            <div className="mb-6 grid grid-cols-1 md:grid-cols-3 gap-4">
              {/* Total Settings */}
              <div className="rounded-xl border border-border bg-card p-4">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center">
                    <Icon name="Settings" size={20} className="text-primary" />
                  </div>
                  <div>
                    <div className="text-2xl font-bold text-foreground">{rows.length}</div>
                    <div className="text-xs text-muted-foreground">Total Settings</div>
                  </div>
                </div>
              </div>

              {/* Pending Changes */}
              <div className="rounded-xl border border-border bg-card p-4">
                <div className="flex items-center gap-3">
                  <div className={`w-10 h-10 rounded-lg flex items-center justify-center ${
                    dirtyKeys.length > 0 ? 'bg-warning/10' : 'bg-success/10'
                  }`}>
                    <Icon
                      name={dirtyKeys.length > 0 ? 'AlertCircle' : 'CheckCircle'}
                      size={20}
                      className={dirtyKeys.length > 0 ? 'text-warning' : 'text-success'}
                    />
                  </div>
                  <div>
                    <div className="text-2xl font-bold text-foreground">{dirtyKeys.length}</div>
                    <div className="text-xs text-muted-foreground">Pending Changes</div>
                  </div>
                </div>
              </div>

              {/* Categories */}
              <div className="rounded-xl border border-border bg-card p-4">
                <div className="flex items-center gap-3">
                  <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center">
                    <Icon name="Folder" size={20} className="text-primary" />
                  </div>
                  <div>
                    <div className="text-2xl font-bold text-foreground">{categories.length}</div>
                    <div className="text-xs text-muted-foreground">Categories</div>
                  </div>
                </div>
              </div>
            </div>

            {/* Search & View Mode Bar - Optimized Layout */}
            <div className="mb-6 space-y-3">
              {/* Top Row: Search + View Modes */}
              <div className="flex flex-col md:flex-row gap-3">
                {/* Search */}
                <div className="flex-1">
                  <div className="relative">
                    <Icon
                      name="Search"
                      size={18}
                      className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground"
                    />
                    <input
                      type="text"
                      placeholder="Search settings..."
                      value={searchQuery}
                      onChange={(e) => setSearchQuery(e.target.value)}
                      className="w-full pl-10 pr-4 py-2.5 rounded-xl border border-border bg-card text-sm text-foreground placeholder:text-muted-foreground focus:outline-none focus:ring-2 focus:ring-primary/20"
                    />
                    {searchQuery && (
                      <button
                        onClick={() => setSearchQuery('')}
                        className="absolute right-3 top-1/2 -translate-y-1/2 p-1 hover:bg-muted/30 rounded-lg transition-colors"
                      >
                        <Icon name="X" size={14} className="text-muted-foreground" />
                      </button>
                    )}
                  </div>
                </div>

                {/* View Mode Tabs */}
                <div className="flex gap-2 bg-muted/30 p-1 rounded-xl flex-shrink-0">
                  <button
                    onClick={() => setViewMode('all')}
                    className={`px-3 py-2 rounded-lg text-sm font-medium transition-colors whitespace-nowrap ${
                      viewMode === 'all'
                        ? 'bg-card text-foreground shadow-sm'
                        : 'text-muted-foreground hover:text-foreground'
                    }`}
                  >
                    All
                  </button>
                  <button
                    onClick={() => setViewMode('security')}
                    className={`px-3 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-1.5 whitespace-nowrap ${
                      viewMode === 'security'
                        ? 'bg-card text-foreground shadow-sm'
                        : 'text-muted-foreground hover:text-foreground'
                    }`}
                  >
                    <Icon name="Shield" size={14} />
                    <span className="hidden sm:inline">Security</span>
                  </button>
                  <button
                    onClick={() => setViewMode('email_notifications')}
                    className={`px-3 py-2 rounded-lg text-sm font-medium transition-colors flex items-center gap-1.5 whitespace-nowrap ${
                      viewMode === 'email_notifications'
                        ? 'bg-card text-foreground shadow-sm'
                        : 'text-muted-foreground hover:text-foreground'
                    }`}
                  >
                    <Icon name="Mail" size={14} />
                    <span className="hidden sm:inline">Notifications</span>
                  </button>
                </div>
              </div>

              {/* Bottom Row: Action Buttons */}
              <div className="flex gap-2 justify-end">
                <Button
                  variant="outline"
                  iconName="RefreshCw"
                  iconPosition="left"
                  onClick={load}
                  disabled={isLoading || isSaving}
                  size="sm"
                >
                  <span className="hidden sm:inline">{t('settings.refresh')}</span>
                  <span className="sm:hidden">Refresh</span>
                </Button>

                <Button
                  variant="outline"
                  iconName="RotateCcw"
                  iconPosition="left"
                  onClick={resetAll}
                  disabled={isLoading || isSaving || dirtyKeys.length === 0}
                  size="sm"
                >
                  <span className="hidden sm:inline">Reset All</span>
                  <span className="sm:hidden">Reset</span>
                </Button>

                <Button
                  variant="primary"
                  iconName="Save"
                  iconPosition="left"
                  onClick={save}
                  disabled={isLoading || isSaving || dirtyKeys.length === 0}
                  size="sm"
                >
                  {isSaving ? t('settings.saving') : `${t('common.save')} (${dirtyKeys.length})`}
                </Button>
              </div>
            </div>

            {/* Messages */}
            {error && (
              <div className="mb-5 p-4 rounded-xl border border-destructive/30 bg-destructive/10 text-destructive flex items-start gap-3">
                <Icon name="AlertCircle" size={18} />
                <div className="flex-1 text-sm">{error}</div>
                <Button variant="ghost" size="sm" iconName="X" onClick={() => setError('')} />
              </div>
            )}

            {successMessage && (
              <div className="mb-5 p-4 rounded-xl border border-success/30 bg-success/10 text-success flex items-start gap-3">
                <Icon name="CheckCircle" size={18} />
                <div className="flex-1 text-sm">{successMessage}</div>
                <Button variant="ghost" size="sm" iconName="X" onClick={() => setSuccessMessage('')} />
              </div>
            )}

            {/* Content */}
            {isLoading ? (
              <div className="rounded-2xl border border-border bg-card p-16 flex flex-col items-center justify-center gap-3">
                <Icon name="Loader" size={32} className="animate-spin text-primary" />
                <div className="text-sm text-muted-foreground">{t('settings.messages.loading')}</div>
              </div>
            ) : (
              <div className="space-y-4">
                {filteredCategories.map((category) => {
                  const meta = categoryMeta[category] || { label: category, icon: 'Folder' };

                  // Special handling for email_notifications
                  if (category === 'email_notifications') {
                    return (
                      <div key={category} className="rounded-2xl border border-border bg-card overflow-hidden">
                        <div className="p-4 flex items-center gap-3 bg-muted/30">
                          <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
                            <Icon name={meta.icon} size={20} className="text-primary" />
                          </div>
                          <h2 className="text-lg font-bold text-foreground">{meta.label}</h2>
                        </div>
                        <div className="p-4">
                          <EmailNotificationSettings />
                        </div>
                      </div>
                    );
                  }

                  const categoryRows = searchQuery
                    ? filteredRows.filter(r => r.category === category)
                    : byCategory[category] || [];

                  if (categoryRows.length === 0) return null;

                  return (
                    <SettingsSection
                      key={category}
                      category={category}
                      label={meta.label}
                      icon={meta.icon}
                      rows={categoryRows}
                      draft={draft}
                      original={original}
                      onChangeDraft={(key, value) => {
                        setDraft((prev) => ({ ...prev, [key]: value }));
                      }}
                      defaultExpanded={searchQuery.length > 0}
                    />
                  );
                })}

                {filteredCategories.length === 0 && (
                  <div className="rounded-2xl border border-border bg-card p-16 flex flex-col items-center justify-center gap-3">
                    <Icon name="Search" size={48} className="text-muted-foreground/30" />
                    <div className="text-sm font-medium text-foreground">No settings found</div>
                    <div className="text-xs text-muted-foreground">
                      Try adjusting your search query
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </div>
      </AuthContextNavigator>
    </>
  );
}
